                            productSize.size,
                            productColor.colorName,
                            productImage.imageUrl,
                            saleBid.bidPrice,
                            saleBid.status.stringValue(),
                            sale.status.stringValue(),
                            sellerShipment.status.stringValue(),
                            saleBid.createdDate,
                            saleBid.modifiedDate,
