public class Xpk42RepositoryImpl implements Xpk42RepositoryCustom { private static final com.fream.back.domain.m17.entity.QXpk42 notice = com.fream.back.domain.m17.entity.QXpk42.xpk42;

    private final JPAQueryFactory queryFactory;

    @Override
    public Page<Xpk42> searchNotices(String keyword, Pageable pageable) {
        BooleanBuilder builder = new BooleanBuilder();


        if (StringUtils.hasText(keyword)) {
            builder.and(containsKeyword(keyword));
        }


        List<Xpk42> results = queryFactory.selectFrom(notice)
                .where(builder)
                .orderBy(notice.createdDate.desc())
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();


        Long total = queryFactory.select(notice.count())
                .from(notice)
                .where(builder)
                .fetchOne();

        return new PageImpl<>(results, pageable, Objects.requireNonNullElse(total, 0L));
    }

    @Override
    public Page<Xpk42> searchNoticesByCategoryAndKeyword(Xkc19 category, String keyword, Pageable pageable) {
        BooleanBuilder builder = new BooleanBuilder();


        if (category != null) {
            builder.and(notice.category.eq(category));
        }


        if (StringUtils.hasText(keyword)) {
            builder.and(containsKeyword(keyword));
        }


        List<Xpk42> results = queryFactory.selectFrom(notice)
                .where(builder)
                .orderBy(notice.createdDate.desc())
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();


        Long total = queryFactory.select(notice.count())
                .from(notice)
                .where(builder)
                .fetchOne();

        return new PageImpl<>(results, pageable, Objects.requireNonNullElse(total, 0L));
    }







    private BooleanExpression containsKeyword(String keyword) {
        return notice.title.containsIgnoreCase(keyword)
                .or(notice.content.containsIgnoreCase(keyword));
    }
}    @Override
    public Page<Xbx83> searchFAQs(String keyword, Pageable pageable) {
        BooleanBuilder builder = new BooleanBuilder();

        if (keyword != null && !keyword.isEmpty()) {

            builder.or(fAQ.question.like("%" + keyword + "%"))
                    .or(fAQ.answer.like("%" + keyword + "%"));
        }

        List<Xbx83> results = queryFactory.selectFrom(fAQ)
                .where(builder)
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();

        long total = queryFactory.select(fAQ.count())
                .from(fAQ)
                .where(builder)
                .fetchOne();

        return new PageImpl<>(results, pageable, total);
    }
}

    @Override
    public List<Xvb31> findRecentQuestionsByClientIp(String clientIp, int limit) {
        log.debug("IP 주소별 최근 질문 조회 쿼리 실행: clientIp={}, limit={}", clientIp, limit);

        return queryFactory
                .selectFrom(chatQuestion)
                .where(
                        chatQuestion.clientIp.eq(clientIp)
                                .and(chatQuestion.user.isNull())
                )
                .orderBy(chatQuestion.createdAt.desc())
                .limit(limit)
                .fetch();
    }

    @Override
    public Page<Xvb31> searchQuestionsByKeyword(String keyword, Pageable pageable) {
        log.debug("키워드로 질문 검색 쿼리 실행: keyword={}, page={}, size={}",
                keyword, pageable.getPageNumber(), pageable.getPageSize());

        BooleanBuilder builder = new BooleanBuilder();


        if (StringUtils.hasText(keyword)) {
            builder.and(
                    chatQuestion.question.containsIgnoreCase(keyword)
                            .or(chatQuestion.answer.containsIgnoreCase(keyword))
            );
        }


        long total = queryFactory
                .selectFrom(chatQuestion)
                .where(builder)
                .fetchCount();


        List<Xvb31> results = queryFactory
                .selectFrom(chatQuestion)
                .where(builder)
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .orderBy(chatQuestion.createdAt.desc())
                .fetch();

        return new PageImpl<>(results, pageable, total);
    }
}
